/* ======================================================================
 *  word_stats.js — vocabulary statistics for the project, each class and
 *  each subject
 *
 *  Counts come from js/word_stats_summary.js (small, loaded with the page).
 *  The word lists live in js/word_stats_words.js (large) and are loaded on
 *  demand with a <script> tag so it also works when index.html is opened
 *  straight from disk (file://). Both are generated by
 *  tools/word_stats/build_word_stats.js.
 *
 *  Shown in three places:
 *    • Home → "Project Stats" tab           SBWordStats.renderPanel(el, 'project')
 *    • every class page, below the covers    (goToSubjects wrapper)
 *    • every subject, a "Word Stats" tab at the right end of the tab bar
 *  Clicking a tile opens the word explorer: one row per word with English,
 *  Urdu, Pashto and Arabic columns. The word's own language is filled from
 *  the books; the other three come from the offline dictionary and, page by
 *  page, from the same online engine the universal translator uses.
 *
 *  Public API: window.SBWordStats
 * ====================================================================== */
(function () {
  'use strict';

  const LANGS = ['en', 'ur', 'ps', 'ar'];
  const INFO = {
    all: { label: 'Distinct Words', sub: 'All four languages', icon: '🔤', color: '#0284c7' },
    en: { label: 'English Words', sub: 'English', icon: 'Aa', color: '#059669', native: 'English', dir: 'ltr', cls: 'ut-en' },
    ur: { label: 'Urdu Words', sub: 'اردو', icon: 'ا', color: '#7c3aed', native: 'اردو', dir: 'rtl', cls: 'ut-ur' },
    ps: { label: 'Pashto Words', sub: 'پښتو', icon: 'ښ', color: '#d97706', native: 'پښتو', dir: 'rtl', cls: 'ut-ps' },
    ar: { label: 'Arabic Words', sub: 'العربية', icon: 'ع', color: '#e11d48', native: 'العربية', dir: 'rtl', cls: 'ut-ar' }
  };
  const PAGE = 100;
  const WORDS_SRC = 'js/word_stats_words.js?v=20261014_ws2';

  const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
  const fmt = n => Number(n || 0).toLocaleString('en-US');
  const summary = () => window.SB_WORD_STATS_SUMMARY || null;

  // ── scope helpers ───────────────────────────────────────────────────────
  function catalogue() {
    try { return (typeof DATA !== 'undefined' && DATA) ? DATA : null; } catch (e) { return null; }
  }
  function scopeCounts(scope) {
    const S = summary();
    if (!S) return null;
    if (scope === 'project') return S.project;
    return S.classes[scope] || S.subjects[scope] || null;
  }
  function scopeName(scope) {
    if (scope === 'project') return 'Whole Project';
    const D = catalogue();
    if (!D) return scope;
    const cls = (D.classes || []).find(c => c.id === scope);
    if (cls) return cls.name;
    const cid = scope.split('-')[0];
    const c = (D.classes || []).find(x => x.id === cid);
    const s = ((D.subjects || {})[cid] || []).find(x => x.id === scope);
    return (s ? s.name : scope) + (c ? ' · ' + c.name : '');
  }

  // the language a subject's book is written in; its Word Stats show only that language
  const URDU_MEDIUM = /-(urdu|isl|islopt|ikhtiari|ishist|islhist|pakstudy|pak|civics|sstum|econ)$/;
  function mediumOf(scope) {
    const S = summary();
    if (!S || !S.subjects[scope]) return null;
    if (/-pashto$/.test(scope)) return 'ps';
    if (/-(arabic|nazira|quran|mq)$/.test(scope)) return 'ar';
    if (URDU_MEDIUM.test(scope)) return 'ur';
    if (/^cls(6|7|9|10|11|12)-hpe$/.test(scope)) return 'ur'; // Class 8 HPE is stored in English
    return 'en';
  }

  // ── stats panel (tiles) ─────────────────────────────────────────────────
  function tilesHtml(scope, counts) {
    const med = mediumOf(scope);
    return (med ? [med] : ['all'].concat(LANGS)).map(k => {
      const i = INFO[k];
      return `
        <button type="button" class="ws-tile" style="--ws-c:${i.color}" onclick="SBWordStats.openExplorer('${scope}','${k}')"
          title="Show every ${k === 'all' ? 'distinct' : i.native} word">
          <span class="ws-tile-icon ${i.cls || ''}" aria-hidden="true">${i.icon}</span>
          <span class="ws-tile-body">
            <span class="ws-tile-label">${i.label}</span>
            <span class="ws-tile-val">${fmt(counts[k])}</span>
            <span class="ws-tile-sub ${i.cls || ''}">${k === 'all' ? i.sub : 'Tap to see every word'}</span>
          </span>
        </button>`;
    }).join('');
  }

  function renderPanel(el, scope, opts) {
    if (!el) return;
    opts = opts || {};
    const counts = scopeCounts(scope);
    if (!counts) {
      el.innerHTML = `<div class="ws-panel"><div class="ws-empty">No book text has been indexed for ${esc(scopeName(scope))} yet.</div></div>`;
      return;
    }
    const S = summary();
    let breakdown = '';
    if (scope === 'project' && S) {
      const D = catalogue();
      const classes = ((D && D.classes) || []).filter(c => S.classes[c.id]);
      breakdown = `
        <div class="ws-breakdown">
          <div class="ws-breakdown-title">Words per class <span>tap a class to open its word list</span></div>
          <div class="ws-table-scroll">
          <table class="ws-btable">
            <thead><tr><th>Class</th><th>Distinct</th><th>English</th><th>Urdu</th><th>Pashto</th><th>Arabic</th></tr></thead>
            <tbody>${classes.map(c => {
              const k = S.classes[c.id];
              return `<tr onclick="SBWordStats.openExplorer('${c.id}','all')"><th>${esc(c.name)}</th><td>${fmt(k.all)}</td><td>${fmt(k.en)}</td><td>${fmt(k.ur)}</td><td>${fmt(k.ps)}</td><td>${fmt(k.ar)}</td></tr>`;
            }).join('')}</tbody>
          </table>
          </div>
        </div>`;
    }
    const title = opts.title || (scope === 'project' ? 'Project Vocabulary' : 'Vocabulary of ' + scopeName(scope));
    el.innerHTML = `
      <section class="ws-panel" aria-label="${esc(title)}">
        <div class="ws-panel-head">
          <div class="ws-panel-title"><span aria-hidden="true">📚</span> ${esc(title)}</div>
          <div class="ws-panel-note">Distinct words in the book text · numbers, equations and symbols excluded${S ? ' · indexed ' + esc(S.generated) : ''}</div>
        </div>
        <div class="ws-tiles">${tilesHtml(scope, counts)}</div>
        ${breakdown}
      </section>`;
  }

  // ── word data (lazy) ────────────────────────────────────────────────────
  let wordsPromise = null;
  const decoded = {};
  function loadWords() {
    if (window.SB_WORD_STATS_WORDS) return Promise.resolve(window.SB_WORD_STATS_WORDS);
    if (wordsPromise) return wordsPromise;
    wordsPromise = new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = WORDS_SRC;
      s.async = true;
      s.onload = () => window.SB_WORD_STATS_WORDS ? resolve(window.SB_WORD_STATS_WORDS) : reject(new Error('empty'));
      s.onerror = () => { wordsPromise = null; reject(new Error('load failed')); };
      document.head.appendChild(s);
    });
    return wordsPromise;
  }
  function langWords(W, L) {
    if (!decoded[L]) {
      decoded[L] = {
        words: W.words[L] ? W.words[L].split('\n') : [],
        freq: W.freq[L] ? W.freq[L].split(',').map(x => parseInt(x, 36)) : []
      };
    }
    return decoded[L];
  }
  const scopeCache = new Map();
  function scopeIndices(W, scope, L) {
    const key = scope + '|' + L;
    if (scopeCache.has(key)) return scopeCache.get(key);
    let out;
    if (scope === 'project') {
      out = null; // every word of the language
    } else {
      const enc = W.scopes[scope] && W.scopes[scope][L];
      out = [];
      if (enc) {
        let prev = -1;
        for (const part of enc.split(',')) { prev += parseInt(part, 36); out.push(prev); }
      }
    }
    scopeCache.set(key, out);
    return out;
  }

  // rows of one language: [{w, lang, n}] in frequency order
  function rowsFor(W, scope, L) {
    const lw = langWords(W, L);
    const idx = scopeIndices(W, scope, L);
    const list = idx ? idx : lw.words.map((_, i) => i);
    return list.map(i => ({ w: lw.words[i], lang: L, n: lw.freq[i] || 0 }));
  }

  // ── translation (offline dictionary first, then batched online) ─────────
  const TCACHE_MAX = 30000;
  const tcache = {};
  function tStore(pair) {
    if (!tcache[pair]) {
      let obj = {};
      try { obj = JSON.parse(localStorage.getItem('sbWS:t:' + pair) || '{}') || {}; } catch (e) { obj = {}; }
      tcache[pair] = obj;
    }
    return tcache[pair];
  }
  let saveTimer = null;
  function tSave() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(() => {
      for (const pair of Object.keys(tcache)) {
        try {
          let obj = tcache[pair];
          const keys = Object.keys(obj);
          if (keys.length > TCACHE_MAX) { obj = {}; keys.slice(-TCACHE_MAX).forEach(k => { obj[k] = tcache[pair][k]; }); tcache[pair] = obj; }
          localStorage.setItem('sbWS:t:' + pair, JSON.stringify(obj));
        } catch (e) { /* quota or private mode — memory cache still works */ }
      }
    }, 600);
  }

  function dictionary(word, tgt) {
    if (tgt !== 'ur' && tgt !== 'ps') return '';
    let e = null;
    try {
      if (typeof window.lookupEngWord === 'function') e = window.lookupEngWord(word);
      if (!e && typeof ENG_URDU_DICT !== 'undefined') e = ENG_URDU_DICT[word];
    } catch (err) { e = null; }
    if (!e) return '';
    const v = tgt === 'ur' ? e.u : e.p;
    if (!v || v.toLowerCase() === word || /^اردو معنی/.test(v)) return '';
    return v;
  }

  async function translateMany(words, src, tgt) {
    const pair = src + '>' + tgt;
    const store = tStore(pair);
    const out = {};
    const todo = [];
    for (const w of words) {
      if (store[w] != null) { out[w] = store[w]; continue; }
      const d = src === 'en' ? dictionary(w, tgt) : '';
      if (d) { out[w] = d; continue; }
      todo.push(w);
    }
    for (let i = 0; i < todo.length; i += 40) {
      const chunk = todo.slice(i, i + 40);
      let lines = null;
      // no batch request to a website: each word goes through SBTranslate (dictionary and word lists on the device)
      if (lines) {
        chunk.forEach((w, j) => { out[w] = lines[j] || ''; if (lines[j]) store[w] = lines[j]; });
      } else if (window.SBTranslate && typeof window.SBTranslate.translate === 'function') {
        for (const w of chunk) {
          try {
            const r = await window.SBTranslate.translate(w, src, tgt, true);
            out[w] = (r && r.text) || '';
            if (out[w]) store[w] = out[w];
          } catch (e) { out[w] = ''; }
        }
      }
    }
    tSave();
    return out;
  }

  // ── my word progress ("I learnt it" / "I already knew it") ────────────────
  // Kept in this browser like the rest of My Stats; one record per signed-in user.
  // Each entry is "<lang>:<word>" → { s: 'l' (learnt) | 'k' (already knew), t: time }.
  const MARK = {
    l: { label: 'Learnt', icon: '✅', title: 'I learnt this word' },
    k: { label: 'Knew it', icon: '⭐', title: 'I already knew this word' }
  };
  let progress = null;
  function progressKey() {
    let u = null;
    try { u = window.SpaceBookAuth && window.SpaceBookAuth.user; } catch (e) { u = null; }
    const id = u && (u.id || u.email || u.name);
    return 'sbWS:progress:' + (id ? String(id).toLowerCase() : 'guest');
  }
  function loadProgress() {
    const key = progressKey();
    if (progress && progress.key === key) return progress;
    let words = {};
    try { words = (JSON.parse(localStorage.getItem(key) || '{}') || {}).words || {}; } catch (e) { words = {}; }
    progress = { key, words };
    return progress;
  }
  function saveProgress() {
    try { localStorage.setItem(progress.key, JSON.stringify({ v: 1, words: progress.words })); } catch (e) { /* storage full or blocked */ }
  }
  const markOf = (lang, w) => { const e = loadProgress().words[lang + ':' + w]; return e ? e.s : ''; };
  function setMark(lang, w, s) {
    const P = loadProgress();
    const k = lang + ':' + w;
    if (!s || (P.words[k] && P.words[k].s === s)) delete P.words[k];
    else P.words[k] = { s, t: Date.now() };
    saveProgress();
    mirrorMark(k, P.words[k]);
    refreshMyWords();
    return P.words[k] ? P.words[k].s : '';
  }
  // A marked word follows the student to every device (user item "word", js/core/items.js).
  function mirrorMark(k, e) {
    const I = window.SBItems;
    if (!I) return;
    if (e) I.put('word', k, { s: e.s }, { at: e.t }); else I.del('word', k);
  }
  function adoptMarks() {                       // words marked before they were synced (or as a guest) go in once
    const I = window.SBItems;
    if (!I) return;
    const w = loadProgress().words;
    I.adopt('word', Object.keys(w).map(k => ({ key: k, value: { s: w[k].s }, at: w[k].t })));
  }
  function listenMarks() {
    const I = window.SBItems;
    if (!I) return;
    I.on('change', e => {                       // a mark made on another device
      if (e.kind !== 'word' || e.origin !== 'remote') return;
      const P = loadProgress();
      if (e.value) P.words[e.key] = { s: e.value.s, t: e.at || Date.now() }; else delete P.words[e.key];
      saveProgress();
      refreshMyWords();
    });
  }
  // ↺ Reset on the My Vocabulary card: every word this student marked Learnt / Knew it goes back to unmarked. The books and word lists stay.
  // The marks are items of the account too (kind "word"), so each one gets a tombstone and does not come back with the next sync.
  // opts.ask === false skips the question (the app asks in its own dialog). Returns how many marks were cleared, or false when the student said no.
  async function resetWords(opts) {
    const P = loadProgress(), I = window.SBItems;
    const keys = new Set(Object.keys(P.words));
    try { if (I) I.list('word').forEach(x => keys.add(x.key)); } catch (e) { /* items not loaded */ }
    if (!keys.size) return 0;
    if (!(opts && opts.ask === false) && !confirm(`Reset your vocabulary statistics? The ${fmt(keys.size)} words you marked ✅ Learnt or ⭐ Knew it will be cleared, and so will the counts for today, the last 7 days and each language. The books and their word lists stay. This cannot be undone.`)) return false;
    if (I) {
      let n = 0;
      for (const k of keys) {
        try { await I.del('word', k); } catch (e) { /* the mark is cleared on this device anyway */ }
        if (++n % 200 === 0) await new Promise(r => setTimeout(r, 0));     // thousands of marks: let the page breathe
      }
    }
    P.words = {};
    saveProgress();
    refreshMyWords();
    return keys.size;
  }
  function progressSummary() {
    const P = loadProgress();
    const out = { learnt: 0, knew: 0, today: 0, week: 0, byLang: {} };
    LANGS.forEach(L => { out.byLang[L] = { learnt: 0, knew: 0 }; });
    const dayStart = new Date(); dayStart.setHours(0, 0, 0, 0);
    const weekStart = dayStart.getTime() - 6 * 864e5;
    for (const [k, e] of Object.entries(P.words)) {
      const L = k.slice(0, 2);
      if (!out.byLang[L]) continue;
      if (e.s === 'l') {
        out.learnt++; out.byLang[L].learnt++;
        if (e.t >= dayStart.getTime()) out.today++;
        if (e.t >= weekStart) out.week++;
      } else if (e.s === 'k') { out.knew++; out.byLang[L].knew++; }
    }
    out.total = out.learnt + out.knew;
    return out;
  }

  // "My Vocabulary" card on the home page (My Stats tab)
  function renderMyWords(el) {
    el = el || document.getElementById('homeMyWords');
    if (!el) return;
    const p = progressSummary();
    const S = summary();
    const projectTotal = S ? S.project.all : 0;
    const pct = projectTotal ? Math.min(100, (p.total / projectTotal) * 100) : 0;
    el.innerHTML = `
      <section class="ws-my" aria-label="My vocabulary">
        <div class="ws-my-head">
          <div class="ws-my-title"><span aria-hidden="true">🧠</span> My Vocabulary</div>
          <div class="ws-my-actions">
            <button type="button" class="ws-my-btn ws-my-primary" onclick="SBWordStats.openExplorer('project','all','new')">🆕 Learn new words</button>
            <button type="button" class="ws-my-btn" onclick="SBWordStats.openExplorer('project','all','l')" ${p.learnt ? '' : 'disabled'}>✅ Review learnt words</button>
            <button type="button" class="ws-my-btn" onclick="SBWordStats.resetWords()" title="Set the word statistics back to zero" ${p.total ? '' : 'disabled'}>↺ Reset</button>
          </div>
        </div>
        <div class="ws-my-grid">
          <div class="ws-my-stat" style="--ws-c:#059669"><span class="ws-my-val">${fmt(p.learnt)}</span><span class="ws-my-lbl">✅ Words learnt</span></div>
          <div class="ws-my-stat" style="--ws-c:#d97706"><span class="ws-my-val">${fmt(p.knew)}</span><span class="ws-my-lbl">⭐ Already knew</span></div>
          <div class="ws-my-stat" style="--ws-c:#0284c7"><span class="ws-my-val">${fmt(p.today)}</span><span class="ws-my-lbl">Learnt today</span></div>
          <div class="ws-my-stat" style="--ws-c:#7c3aed"><span class="ws-my-val">${fmt(p.week)}</span><span class="ws-my-lbl">Learnt in 7 days</span></div>
        </div>
        <div class="ws-my-langs">
          ${LANGS.map(L => `<div class="ws-my-lang ws-col-${L}"><span class="${INFO[L].cls}">${L === 'en' ? 'English' : INFO[L].native}</span><b>${fmt(p.byLang[L].learnt + p.byLang[L].knew)}</b><small>${fmt(p.byLang[L].learnt)} learnt · ${fmt(p.byLang[L].knew)} knew</small></div>`).join('')}
        </div>
        <div class="ws-my-bar" title="${pct.toFixed(2)}% of all project words"><div style="width:${p.total ? Math.max(pct, 0.6) : 0}%"></div></div>
        <div class="ws-my-note">${fmt(p.total)} of ${fmt(projectTotal)} project words marked (${pct < 0.1 && p.total ? 'under 0.1' : pct.toFixed(1)}%). Tap ✅ Learnt or ⭐ Knew it next to any word in a word list.</div>
      </section>`;
  }
  function refreshMyWords() {
    const el = document.getElementById('homeMyWords');
    if (el) renderMyWords(el);
  }

  // ── word explorer modal ─────────────────────────────────────────────────
  const ex = { scope: 'project', lang: 'all', page: 0, q: '', status: 'all', rows: [], filtered: [], req: 0, W: null, translating: false };
  let modal = null;

  function ensureModal() {
    if (modal) return modal;
    modal = document.createElement('div');
    modal.className = 'ws-modal-backdrop';
    modal.hidden = true;
    modal.innerHTML = `
      <div class="ws-modal" role="dialog" aria-modal="true" aria-labelledby="wsModalTitle">
        <div class="ws-modal-head">
          <div>
            <div class="ws-modal-title" id="wsModalTitle"></div>
            <div class="ws-modal-sub" id="wsModalSub"></div>
          </div>
          <button type="button" class="ws-close" aria-label="Close" onclick="SBWordStats.closeExplorer()">✕</button>
        </div>
        <div class="ws-modal-tools">
          <div class="ws-chips" id="wsChips" role="tablist"></div>
          <div class="ws-status" id="wsStatus" role="group" aria-label="Show"></div>
          <input type="search" class="ws-search" id="wsSearch" placeholder="Search words…" autocomplete="off" spellcheck="false">
        </div>
        <div class="ws-table-wrap" id="wsTableWrap"></div>
        <div class="ws-pager" id="wsPager"></div>
      </div>`;
    document.body.appendChild(modal);
    modal.addEventListener('mousedown', e => { if (e.target === modal) closeExplorer(); });
    const search = modal.querySelector('#wsSearch');
    let t = null;
    search.addEventListener('input', () => { clearTimeout(t); t = setTimeout(() => { ex.q = search.value.trim(); ex.page = 0; applyFilter(); drawTable(); }, 200); });
    document.addEventListener('keydown', e => { if (e.key === 'Escape' && modal && !modal.hidden) closeExplorer(); });
    // ✅ / ⭐ buttons in each row
    modal.addEventListener('click', e => {
      const b = e.target.closest && e.target.closest('.ws-mark');
      if (!b) return;
      const tr = b.closest('tr');
      const st = setMark(tr.getAttribute('data-l'), tr.getAttribute('data-w'), b.getAttribute('data-s'));
      paintRow(tr, st);
      drawStatus();
    });
    return modal;
  }

  function drawChips() {
    const counts = scopeCounts(ex.scope) || {};
    const med = mediumOf(ex.scope);
    modal.querySelector('#wsChips').innerHTML = med ? '' : ['all'].concat(LANGS).map(k =>
      `<button type="button" role="tab" class="ws-chip ${ex.lang === k ? 'active' : ''}" style="--ws-c:${INFO[k].color}" onclick="SBWordStats.setLang('${k}')">${k === 'all' ? 'All' : INFO[k].native} <b>${fmt(counts[k])}</b></button>`
    ).join('');
  }

  function drawStatus() {
    const el = modal.querySelector('#wsStatus');
    if (!el) return;
    let l = 0, k = 0;
    const P = loadProgress().words;
    for (const r of ex.rows) { const e = P[r.lang + ':' + r.w]; if (e) { if (e.s === 'l') l++; else k++; } }
    const opts = [['all', 'All', ex.rows.length], ['new', '🆕 New', ex.rows.length - l - k], ['l', '✅ Learnt', l], ['k', '⭐ Knew', k]];
    el.innerHTML = opts.map(([id, label, n]) =>
      `<button type="button" class="ws-st ${ex.status === id ? 'active' : ''}" onclick="SBWordStats.setStatus('${id}')">${label} <b>${fmt(n)}</b></button>`).join('');
  }

  // alphabetical order in each language's own alphabet
  const COLLATORS = {};
  const collator = L => COLLATORS[L] || (COLLATORS[L] = new Intl.Collator(L === 'en' ? 'en' : L, { sensitivity: 'base', numeric: true }));
  const sortedCache = new Map();
  function sortedRows(W, scope, L) {
    const key = scope + '|' + L;
    if (!sortedCache.has(key)) {
      const c = collator(L);
      sortedCache.set(key, rowsFor(W, scope, L).sort((a, b) => c.compare(a.w, b.w) || (a.w < b.w ? -1 : a.w > b.w ? 1 : 0)));
    }
    return sortedCache.get(key);
  }

  function buildRows() {
    const W = ex.W;
    if (ex.lang === 'all') {
      // English A–Z first, then Urdu, Pashto and Arabic, each in its own alphabetical order
      ex.rows = [].concat(...LANGS.map(L => sortedRows(W, ex.scope, L)));
    } else {
      ex.rows = sortedRows(W, ex.scope, ex.lang);
    }
    applyFilter();
  }

  function applyFilter() {
    const q = ex.q.toLowerCase();
    const P = loadProgress().words;
    const st = ex.status;
    ex.filtered = (q || st !== 'all') ? ex.rows.filter(r => {
      if (q && r.w.indexOf(q) === -1) return false;
      if (st === 'all') return true;
      const e = P[r.lang + ':' + r.w];
      return st === 'new' ? !e : !!e && e.s === st;
    }) : ex.rows;
  }

  function cell(lang, text, isSource) {
    const i = INFO[lang];
    return `<td class="ws-cell ws-col-${lang} ${i.cls} ${isSource ? 'ws-src' : ''}" dir="${i.dir}" data-l="${lang}">${text}</td>`;
  }

  function marksHtml(s) {
    return Object.keys(MARK).map(id =>
      `<button type="button" class="ws-mark ws-mark-${id} ${s === id ? 'on' : ''}" data-s="${id}" title="${MARK[id].title}" aria-pressed="${s === id}">${MARK[id].icon}<span>${MARK[id].label}</span></button>`).join('');
  }
  function paintRow(tr, s) {
    tr.classList.toggle('ws-row-l', s === 'l');
    tr.classList.toggle('ws-row-k', s === 'k');
    const td = tr.querySelector('.ws-marks');
    if (td) td.innerHTML = marksHtml(s);
  }

  function drawTable() {
    const wrap = modal.querySelector('#wsTableWrap');
    const pager = modal.querySelector('#wsPager');
    const total = ex.filtered.length;
    const pages = Math.max(1, Math.ceil(total / PAGE));
    if (ex.page >= pages) ex.page = pages - 1;
    const start = ex.page * PAGE;
    const slice = ex.filtered.slice(start, start + PAGE);
    if (!slice.length) {
      const why = ex.q ? 'No word matches “' + esc(ex.q) + '”.'
        : ex.status === 'l' ? 'No words marked ✅ Learnt here yet. Tap ✅ next to a word once you have learnt it.'
        : ex.status === 'k' ? 'No words marked ⭐ Knew it here yet.'
        : ex.status === 'new' ? 'Well done, every word in this list is marked!' : 'No words in this list.';
      wrap.innerHTML = `<div class="ws-empty">${why}</div>`;
      pager.innerHTML = '';
      return;
    }
    wrap.innerHTML = `
      <table class="ws-wtable">
        <thead><tr><th class="ws-num">#</th>${LANGS.map(L => `<th class="ws-col-${L} ${INFO[L].cls}">${L === 'en' ? 'English' : INFO[L].native + ' <small>' + ({ ur: 'Urdu', ps: 'Pashto', ar: 'Arabic' })[L] + '</small>'}</th>`).join('')}<th class="ws-num" title="How many times the word appears across all books">Uses</th><th class="ws-marks-h">My progress</th></tr></thead>
        <tbody>${slice.map((r, i) => { const s = markOf(r.lang, r.w); return `
          <tr data-w="${esc(r.w)}" data-l="${r.lang}" class="${s ? 'ws-row-' + s : ''}">
            <td class="ws-num">${fmt(start + i + 1)}</td>
            ${LANGS.map(L => cell(L, L === r.lang ? esc(r.w) : '<span class="ws-wait">…</span>', L === r.lang)).join('')}
            <td class="ws-num">${fmt(r.n)}</td>
            <td class="ws-marks">${marksHtml(s)}</td>
          </tr>`; }).join('')}
        </tbody>
      </table>`;
    pager.innerHTML = `
      <button type="button" class="ws-pg" ${ex.page === 0 ? 'disabled' : ''} onclick="SBWordStats.go(-1)">‹ Prev</button>
      <span class="ws-pg-info">Page ${fmt(ex.page + 1)} of ${fmt(pages)} · ${fmt(total)} words</span>
      <button type="button" class="ws-pg" ${ex.page >= pages - 1 ? 'disabled' : ''} onclick="SBWordStats.go(1)">Next ›</button>`;
    wrap.scrollTop = 0;
    fillTranslations(slice);
  }

  async function fillTranslations(slice) {
    const req = ++ex.req;
    const bySrc = {};
    for (const r of slice) (bySrc[r.lang] = bySrc[r.lang] || []).push(r.w);
    const jobs = [];
    for (const src of Object.keys(bySrc)) {
      for (const tgt of LANGS) {
        if (tgt === src) continue;
        jobs.push(translateMany(bySrc[src], src, tgt).then(map => {
          if (req !== ex.req || !modal || modal.hidden) return;
          modal.querySelectorAll(`#wsTableWrap tr[data-l="${src}"]`).forEach(tr => {
            const w = tr.getAttribute('data-w');
            const td = tr.querySelector(`td[data-l="${tgt}"]`);
            if (!td || !(w in map)) return;
            const v = map[w];
            td.innerHTML = v && v.toLowerCase() !== w ? esc(v) : '<span class="ws-none">—</span>';
          });
        }).catch(() => {}));
      }
    }
    await Promise.all(jobs);
    if (req !== ex.req || !modal) return;
    modal.querySelectorAll('#wsTableWrap .ws-wait').forEach(s => { s.className = 'ws-none'; s.textContent = '—'; });
  }

  function setTitle() {
    const counts = scopeCounts(ex.scope) || {};
    modal.querySelector('#wsModalTitle').textContent = (ex.lang === 'all' ? 'Distinct Words' : INFO[ex.lang].label) + ' — ' + scopeName(ex.scope);
    modal.querySelector('#wsModalSub').textContent = fmt(ex.lang === 'all' ? counts.all : counts[ex.lang]) +
      ' words from the book text in alphabetical order. Tap ✅ Learnt when you learn a word or ⭐ Knew it if you already knew it.';
  }

  async function openExplorer(scope, lang, status) {
    ensureModal();
    ex.scope = scope; ex.lang = mediumOf(scope) || lang || 'all'; ex.page = 0; ex.q = ''; ex.status = status || 'all';
    ex.rows = [];
    modal.querySelector('#wsStatus').innerHTML = '';
    modal.classList.remove('ws-chooser');
    modal.querySelector('#wsSearch').value = '';
    modal.hidden = false;
    document.body.classList.add('ws-modal-open');
    setTitle();
    drawChips();
    modal.querySelector('#wsPager').innerHTML = '';
    modal.querySelector('#wsTableWrap').innerHTML = '<div class="ws-empty"><span class="ws-spinner"></span> Loading word lists…</div>';
    try {
      ex.W = await loadWords();
    } catch (e) {
      modal.querySelector('#wsTableWrap').innerHTML = '<div class="ws-empty">The word list could not be loaded. Please reload the page and try again.</div>';
      return;
    }
    if (modal.hidden) return;
    buildRows();
    drawStatus();
    drawTable();
    setTimeout(() => modal.querySelector('#wsSearch').focus({ preventScroll: true }), 50);
  }

  function setLang(lang) {
    if (!ex.W) return;
    ex.lang = lang; ex.page = 0;
    setTitle(); drawChips(); buildRows(); drawStatus(); drawTable();
  }
  function setStatus(st) {
    if (!ex.W) return;
    ex.status = st; ex.page = 0;
    applyFilter(); drawStatus(); drawTable();
  }
  function go(d) { ex.page += d; if (ex.page < 0) ex.page = 0; drawTable(); }
  function closeExplorer() {
    if (!modal) return;
    modal.hidden = true;
    ex.req++;
    document.body.classList.remove('ws-modal-open');
  }

  // ── class pages: stats below the cover pages ────────────────────────────
  let classPagesHooked = false;
  function hookClassPages() {
    if (typeof window.goToSubjects !== 'function' || classPagesHooked) return;
    classPagesHooked = true;
    SBHooks.use('goToSubjects', function (orig) {
      return function (classId) {
        const out = orig.apply(this, arguments);
        try {
          const body = document.getElementById('dashboard-body');
          if (body && scopeCounts(classId) && !body.querySelector('.ws-class-stats')) {
            const holder = document.createElement('div');
            holder.className = 'ws-class-stats';
            body.appendChild(holder);
            renderPanel(holder, classId, { title: 'Vocabulary of ' + scopeName(classId) + ' books' });
          }
        } catch (e) { /* stats are optional */ }
        return out;
      };
    });
  }

  // ── subjects: a "Word Stats" tab at the right end of the tab bar ────────
  let lastSubject = null;
  let subjectsHooked = false;
  function hookSubjects() {
    if (typeof window.openSubject !== 'function' || subjectsHooked) return;
    subjectsHooked = true;
    SBHooks.use('openSubject', function (orig) {
      return function (classId, subjId) {
        lastSubject = { classId, subjId };
        return orig.apply(this, arguments);
      };
    });
  }

  function currentSubject() {
    const S = summary();
    if (!S) return null;
    let st = null;
    try { st = (typeof state !== 'undefined') ? state : null; } catch (e) { st = null; }
    if (!st || st.activeView !== 'subject-detail') return null;
    const cid = st.selectedClass;
    if (lastSubject && lastSubject.classId === cid && S.subjects[lastSubject.subjId]) return lastSubject.subjId;
    const key = st.activeSubject;
    if (cid && key) {
      const guess = String(key).startsWith(cid + '-') ? key : cid + '-' + key;
      if (S.subjects[guess]) return guess;
    }
    return null;
  }

  const LESSON_RX = /\bLessons?\b|لوست|سبق|اسباق|الدرس/i;
  function findLessonTab(root) {
    const cands = root.querySelectorAll('[data-tab="lesson"], button, [role="tab"]');
    for (const b of cands) {
      if (b.classList.contains('ws-subj-tab') || b.closest('.ws-panel, .ws-modal-backdrop, .ut-root')) continue;
      if (b.getAttribute('data-tab') === 'lesson' || LESSON_RX.test(b.textContent || '')) {
        const bar = b.parentElement;
        if (bar && bar.querySelectorAll('button, [role="tab"], [data-tab]').length >= 2) return { tab: b, bar };
      }
    }
    return null;
  }

  function placeSubjectTab() {
    const body = document.getElementById('dashboard-body');
    if (!body) return;
    const subj = currentSubject();
    const existing = body.querySelector('.ws-subj-tab');
    if (!subj) { if (existing) existing.remove(); return; }
    if (existing && existing.dataset.subj === subj && existing.isConnected) return;
    if (existing) existing.remove();
    const found = findLessonTab(body);
    if (!found) return;
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = String(found.tab.className || '').replace(/\bactive\b/g, '').trim() + ' ws-subj-tab';
    btn.dataset.subj = subj;
    btn.title = 'Distinct ' + ((INFO[mediumOf(subj)] || {}).label || 'words').toLowerCase() + ' in this book';
    btn.innerHTML = '📊 Word Stats';
    btn.addEventListener('click', e => { e.preventDefault(); e.stopPropagation(); openSubjectStats(subj); }, true);
    found.bar.appendChild(btn);
    if (window.SBA11y) window.SBA11y.enhance(found.bar);     // it is part of the tab bar for keyboard and screen-reader users
  }

  function openSubjectStats(subj) {
    ensureModal();
    // small chooser first: the tiles, then any tile opens the list
    const counts = scopeCounts(subj);
    if (!counts) return;
    ex.req++;
    modal.hidden = false;
    modal.classList.add('ws-chooser');
    document.body.classList.add('ws-modal-open');
    modal.querySelector('#wsModalTitle').textContent = 'Word Stats — ' + scopeName(subj);
    const med = mediumOf(subj);
    modal.querySelector('#wsModalSub').textContent = med
      ? 'Distinct ' + INFO[med].label.replace(' Words', '') + ' words in this book (the language it is written in). Tap to see every word with its translation.'
      : 'Distinct words in this book. Choose a language to see every word in English, Urdu, Pashto and Arabic.';
    modal.querySelector('#wsChips').innerHTML = '';
    modal.querySelector('#wsStatus').innerHTML = '';
    modal.querySelector('#wsPager').innerHTML = '';
    const wrap = modal.querySelector('#wsTableWrap');
    wrap.innerHTML = `<div class="ws-tiles ws-tiles-modal${med ? " ws-tiles-single" : ""}">${tilesHtml(subj, counts)}</div>`;
  }

  let moTimer = null;
  function watch() {
    const body = document.getElementById('dashboard-body');
    if (!body) return;
    new MutationObserver(() => {
      if (moTimer) return;
      moTimer = setTimeout(() => { moTimer = null; try { placeSubjectTab(); } catch (e) { /* optional */ } }, 120);
    }).observe(body, { childList: true, subtree: true });
  }

  function init() {
    hookClassPages();
    hookSubjects();
    watch();
    placeSubjectTab();
    // the home page may already be on the Project Stats tab
    refreshMyWords();
    listenMarks();
    adoptMarks();
    document.addEventListener('spacebook:auth', () => { progress = null; refreshMyWords(); adoptMarks(); });
    const proj = document.getElementById('homeProjectStats');
    if (proj && !proj.hidden && !proj.firstChild) renderPanel(proj, 'project');
  }

  window.SBWordStats = { renderPanel, renderMyWords, progressSummary, resetWords, openExplorer, closeExplorer, setLang, setStatus, go, scopeCounts, loadWords };
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', init);
  else init();
})();
